// Parse Claude translation JSON; en/de users get text_user without a second translation.
const src = $('Translate Line Request').item.json.body || {};
const lang = String(src.user_language || 'en');
const raw = ($json.content ?? []).filter(c => c.type === 'text').map(c => c.text).join('\n').trim();
const m = raw.match(/\{[\s\S]*\}/);
if (!m) throw new Error('no JSON in translation');
const t = JSON.parse(m[0]);
const textEn = String(t.text_en || '').trim().slice(0, 2000);
if (!textEn) throw new Error('empty text_en');
let textUser = String(t.text_user || '').trim().slice(0, 2000);
if (lang === 'en') textUser = textEn;
if (lang === 'de') textUser = String(src.text_de || '');
if (!textUser) textUser = textEn;
const lineId = String(src.line_id ?? '');
if (!/^\d+$/.test(lineId)) throw new Error('invalid line_id');
return { json: { line_id: lineId, text_en: textEn, text_user: textUser } };
